// One list drives the header, the footer, the sitemap and the head of every plain page, so a page cannot be in
// the menu and missing from the sitemap. Adding a page to the menu is one entry here: `to` is checked against
// the real routes (src/routeTree.gen.ts, regenerated by "npm run routes" when you add a route file), the keys
// are checked against the locale files, and the language-free path and the id are worked out. A page route
// with no entry here fails "npm run typecheck" (see NavCoversEveryPage below) and src/routing.test.ts.
import type { ParseKeys } from 'i18next';
import type { FileRouteTypes } from '@/routeTree.gen';

/**
 * Every page under /$locale that needs no other parameter (the article page needs a slug, so it is out; the
 * splat route that answers unmatched URLs is out too).
 */
export type PageRoute = Exclude<
  Extract<FileRouteTypes['to'], `/$locale${string}`>,
  `${string}/$${string}/$${string}` | '/$locale/$'
>;

type NavInput<To extends PageRoute = PageRoute> = {
  to: To;
  /** Typed keys of t(): a typo fails `npm run typecheck`. */
  labelKey: ParseKeys;
  /** The page's <title> and meta description (see pageHead in src/shared/lib/seo/page-head.ts). */
  metaTitleKey: ParseKeys;
  metaDescriptionKey: ParseKeys;
  changefreq: 'daily' | 'weekly' | 'monthly' | 'yearly';
  priority: number;
};

export type NavItem<To extends PageRoute = PageRoute> = NavInput<To> & {
  /** Stable key: "home" for the language root, otherwise the path without its slash ("about"). */
  id: string;
  /** '' is the language root (/ar). Otherwise the route path without the locale: '/about'. */
  path: string;
};

const LOCALE_PREFIX = '/$locale';

export function navItem<const To extends PageRoute>(input: NavInput<To>): NavItem<To> {
  const path = input.to.slice(LOCALE_PREFIX.length);
  return { ...input, id: path === '' ? 'home' : path.slice(1), path };
}

export const NAV = [
  navItem({
    to: '/$locale',
    labelKey: 'nav.home',
    metaTitleKey: 'home.metaTitle',
    metaDescriptionKey: 'home.metaDescription',
    changefreq: 'weekly',
    priority: 1,
  }),
  navItem({
    to: '/$locale/about',
    labelKey: 'nav.about',
    metaTitleKey: 'about.metaTitle',
    metaDescriptionKey: 'about.metaDescription',
    changefreq: 'monthly',
    priority: 0.7,
  }),
  navItem({
    to: '/$locale/services',
    labelKey: 'nav.services',
    metaTitleKey: 'services.metaTitle',
    metaDescriptionKey: 'services.metaDescription',
    changefreq: 'monthly',
    priority: 0.8,
  }),
  navItem({
    to: '/$locale/news',
    labelKey: 'nav.news',
    metaTitleKey: 'news.metaTitle',
    metaDescriptionKey: 'news.metaDescription',
    changefreq: 'weekly',
    priority: 0.7,
  }),
  navItem({
    to: '/$locale/contact',
    labelKey: 'nav.contact',
    metaTitleKey: 'contact.metaTitle',
    metaDescriptionKey: 'contact.metaDescription',
    changefreq: 'yearly',
    priority: 0.6,
  }),
] as const satisfies readonly NavItem[];

type MissingFromNav = Exclude<PageRoute, (typeof NAV)[number]['to']>;
type NavCoversEveryPage = [MissingFromNav] extends [never]
  ? true
  : {
      'FIX: add a navItem(...) for these routes to NAV in src/config/nav.config.ts': MissingFromNav;
    };
/**
 * Compile-time proof that every page route has a NAV entry (menu, sitemap and the page's title, description and
 * canonical all come from it). A route file added without one fails `npm run typecheck` right here, and the
 * error names the route.
 */
export const navCoversEveryPage: NavCoversEveryPage = true;

/** The NAV entry of a page route. Throws for a route that is not in NAV: a page without a menu entry has no head here. */
export function navItemFor(to: PageRoute): NavItem {
  const found = NAV.find((item) => item.to === to);
  if (found === undefined) {
    throw new Error(`${to} is not in NAV: add a navItem(...) for it in src/config/nav.config.ts`);
  }
  return found;
}

/**
 * The static path segments of NAV ('about', 'news', ...). canonicalRedirectIfExists lowercases these and the
 * language prefix; every other segment is a slug, matched by the content layer (.claude/rules/content.md).
 */
export const PAGE_SEGMENTS: ReadonlySet<string> = new Set(
  NAV.flatMap((item) => item.path.split('/').filter((segment) => segment !== '')),
);

/** The language-free path of every NAV page ('', '/about', ...): the URLs that exist without a slug. */
export const PAGE_PATHS: ReadonlySet<string> = new Set(NAV.map((item) => item.path));
